import {
  Mesh,
  Group,
  PlaneGeometry,
  BoxGeometry,
  CircleGeometry,
  EdgesGeometry,
  LineSegments,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  CanvasTexture,
  LinearSRGBColorSpace,
  Vector3,
  Euler,
  Object3D,
} from 'three/webgpu'
import {
  mix,
  length,
  sub,
  add,
  divide,
  fract,
  step,
  mul,
  texture,
  uv,
  vec2,
  color,
} from 'three/tsl'
import { gsap } from 'gsap'
import '@/primitives'
import '@/text'

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{headline:string, body:string, cta:string}} textContent
 *
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Promise<THREE.Texture>} textureLoader
 * @property {(url:string)=>Promise<THREE.Group>} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D, params:any)=>void}} primitives
 * @property {{[key:string]:(options:any)=>THREE.Mesh}} fontAtlas
 */

/**
 * Create the rich empty‑state panel.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -------------------------------------------------------------------------
  // Constants (derived from the specification)
  // -------------------------------------------------------------------------
  const PANEL_W = 3.2 // scene units
  const PANEL_H = 2.2
  const CORNER_RADIUS = 0.06
  const GRID_PITCH = 0.25
  const GRID_OPACITY = 0.06 // 6 %
  const BORDER_WIDTH = 0.006
  const BORDER_COLOR = '#26262f'

  const GHOST_OPACITY_MIN = 0.24
  const GHOST_OPACITY_MAX = 0.34
  const GHOST_BREATHE_DURATION = 2.4 // seconds

  const CTA_W = 1.5
  const CTA_H = 0.36
  const CTA_PRESS_SCALE = 0.97
  const CTA_PRESS_DURATION = 0.12 // seconds

  const MOUNT_FADE_DURATION = 0.5 // seconds
  const MOUNT_FADE_EASE = [0.25, 0.46, 0.45, 0.94]

  // -------------------------------------------------------------------------
  // Root group
  // -------------------------------------------------------------------------
  const root = new Group()
  if (config.position) root.position.set(...Object.values(config.position))
  if (config.rotation) root.rotation.set(...Object.values(config.rotation))
  if (config.scale) root.scale.set(...Object.values(config.scale))

  // -------------------------------------------------------------------------
  // Helper – plane with node‑material (radial gradient + grid + border)
  // -------------------------------------------------------------------------
  const panelGeometry = new PlaneGeometry(PANEL_W, PANEL_H, 1, 1)

  // Nodes for radial gradient ------------------------------------------------
  const uvNode = uv()
  const centerUV = vec2(0.5, 0.5)
  const radial = length(sub(uvNode, centerUV))

  const gradColorA = color('#14141a')
  const gradColorB = color('#0b0b10')
  const gradientNode = mix(gradColorA, gradColorB, radial)

  // Nodes for grid -----------------------------------------------------------
  const gridScale = float(1 / GRID_PITCH)
  const uvScaled = mul(uvNode, gridScale)
  const gridMask = step(fract(uvScaled), float(0.003)) // thin line ≈ 0.006 / panelSize
  const gridColor = color('#e8ecf2')
  const gridNode = mul(gridColor, mul(gridMask, float(GRID_OPACITY)))

  // Nodes for border ---------------------------------------------------------
  const borderMaskX = step(uvNode.x, float(BORDER_WIDTH / PANEL_W))
  const borderMaskX2 = step(float(1).sub(uvNode.x), float(BORDER_WIDTH / PANEL_W))
  const borderMaskY = step(uvNode.y, float(BORDER_WIDTH / PANEL_H))
  const borderMaskY2 = step(float(1).sub(uvNode.y), float(BORDER_WIDTH / PANEL_H))
  const borderMask = add(add(borderMaskX, borderMaskX2), add(borderMaskY, borderMaskY2))
  const borderColor = color(BORDER_COLOR)
  const borderNode = mul(borderColor, borderMask)

  // Compose final color -------------------------------------------------------
  const finalColor = add(add(gradientNode, gridNode), borderNode)

  const panelMaterial = new MeshStandardNodeMaterial()
  panelMaterial.colorNode = finalColor
  panelMaterial.roughness = 0.6
  panelMaterial.metalness = 0.1
  panelMaterial.transparent = true
  panelMaterial.depthWrite = true
  panelMaterial.side = THREE.DoubleSide

  const panelMesh = new Mesh(panelGeometry, panelMaterial)
  panelMesh.castShadow = false
  panelMesh.receiveShadow = true
  root.add(panelMesh)

  // -------------------------------------------------------------------------
  // Ghost preview (wireframe watch‑card + dial + text bars)
  // -------------------------------------------------------------------------
  const ghostGroup = new Group()
  ghostGroup.position.set(
    -PANEL_W / 2 + 0.5, // left with some padding
    0,
    0.001 // slightly in front to avoid z‑fighting
  )

  // Wireframe rectangle (1.1 × 1.4)
  const wireGeom = new BoxGeometry(1.1, 1.4, 0)
  const wireEdges = new EdgesGeometry(wireGeom)
  const wireMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', opacity: 0.3, transparent: true })
  const wireframe = new LineSegments(wireEdges, wireMat)
  ghostGroup.add(wireframe)

  // Ghost dial (circle, diameter 0.55)
  const dialGeom = new CircleGeometry(0.55 / 2, 32)
  const dialMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', opacity: 0.3, transparent: true })
  const dial = new Mesh(dialGeom, dialMat)
  dial.position.set(0, 0, 0.001)
  ghostGroup.add(dial)

  // Ghost text bars (two)
  const barWidth = 0.7
  const barHeight = 0.06
  const barGeom = new BoxGeometry(barWidth, barHeight, 0)
  const barMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', opacity: 0.22, transparent: true })
  const bar1 = new Mesh(barGeom, barMat)
  const bar2 = new Mesh(barGeom, barMat)
  bar1.position.set(0, -0.2, 0.001)
  bar2.position.set(0, -0.35, 0.001)
  ghostGroup.add(bar1, bar2)

  root.add(ghostGroup)

  // Ghost breathing animation
  const ghostTween = gsap.to(ghostGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: GHOST_BREATHE_DURATION,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    repeat: -1,
    yoyo: true,
    onUpdate() {
      const t = ghostTween.progress()
      const opacity = THREE.MathUtils.lerp(GHOST_OPACITY_MIN, GHOST_OPACITY_MAX, t)
      ghostGroup.traverse((obj) => {
        if (obj.isMesh && obj.material && obj.material.opacity !== undefined) {
          obj.material.opacity = opacity
        }
      })
    },
  })

  // -------------------------------------------------------------------------
  // Text column (headline, body)
  // -------------------------------------------------------------------------
  const textGroup = new Group()
  const columnX = PANEL_W / 2 - 0.5 // right side with padding
  const columnYStart = PANEL_H / 2 - 0.5 // start near top
  textGroup.position.set(columnX, columnYStart, 0.001)

  // Helper to create MSDF text mesh via the fontAtlas utility
  const createText = (txt, opts) => {
    // ctx.fontAtlas is assumed to expose a `createText` function returning a Mesh
    // The exact API may differ; adapt as needed.
    return ctx.fontAtlas.createText({
      text: txt,
      fontFamily: opts.family,
      fontSize: opts.fontSize,
      fontWeight: opts.fontWeight,
      lineHeight: opts.lineHeight,
      letterSpacing: opts.letterSpacing,
      color: opts.color,
    })
  }

  // Headline
  const headlineMesh = createText(config.textContent.headline, {
    family: 'Lora',
    fontSize: 34,
    fontWeight: 600,
    lineHeight: 1.15,
    letterSpacing: -0.01,
    color: '#e8ecf2', // ink = paper color
  })
  headlineMesh.position.set(0, 0, 0)
  textGroup.add(headlineMesh)

  // Body (placed below headline with 0.25 unit baseline rhythm)
  const bodyMesh = createText(config.textContent.body, {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 400,
    lineHeight: 1.5,
    letterSpacing: 0,
    color: '#e8ecf2',
  })
  bodyMesh.position.set(0, -0.35, 0) // approximate spacing
  textGroup.add(bodyMesh)

  root.add(textGroup)

  // -------------------------------------------------------------------------
  // CTA button
  // -------------------------------------------------------------------------
  const buttonGroup = new Group()
  buttonGroup.position.set(columnX, -0.9, 0.001) // below body

  // Button background – vertical gradient on a canvas
  const btnCanvas = new OffscreenCanvas(256, 64)
  const btnCtx = btnCanvas.getContext('2d')
  const btnGrad = btnCtx.createLinearGradient(0, 0, 0, btnCanvas.height)
  btnGrad.addColorStop(0, '#ff4450')
  btnGrad.addColorStop(1, '#c1121f')
  btnCtx.fillStyle = btnGrad
  btnCtx.fillRect(0, 0, btnCanvas.width, btnCanvas.height)
  const btnTexture = new CanvasTexture(btnCanvas)
  btnTexture.colorSpace = LinearSRGBColorSpace
  btnTexture.needsUpdate = true

  const buttonMat = new MeshBasicNodeMaterial({
    map: btnTexture,
    transparent: true,
    side: THREE.DoubleSide,
  })
  const buttonGeom = new PlaneGeometry(CTA_W, CTA_H)
  const buttonMesh = new Mesh(buttonGeom, buttonMat)
  buttonMesh.castShadow = false
  buttonMesh.receiveShadow = false
  buttonGroup.add(buttonMesh)

  // CTA label
  const ctaLabelMesh = createText(config.textContent.cta, {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    lineHeight: 1,
    letterSpacing: 0.08,
    color: '#ff2a38',
  })
  ctaLabelMesh.position.set(0, 0, 0.01)
  buttonGroup.add(ctaLabelMesh)

  // Press interaction (scale animation) – expose via handlers
  const pressTimeline = gsap.timeline({ paused: true })
  pressTimeline.to(buttonGroup.scale, {
    x: CTA_PRESS_SCALE,
    y: CTA_PRESS_SCALE,
    z: CTA_PRESS_SCALE,
    duration: CTA_PRESS_DURATION,
    ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
  })
  pressTimeline.to(
    buttonGroup.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: CTA_PRESS_DURATION,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    },
    `+=0`
  )

  const handlers = {
    pointerdown: () => pressTimeline.play(0),
    pointerup: () => pressTimeline.reverse(),
    pointerout: () => pressTimeline.reverse(),
  }

  buttonGroup.userData.handlers = handlers
  root.userData.handlers = {} // no global handlers required

  root.add(buttonGroup)

  // -------------------------------------------------------------------------
  // Mount animation (fade‑up)
  // -------------------------------------------------------------------------
  root.scale.set(1, 1, 1)
  root.position.y += 0.2
  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.material.transparent = true
      obj.material.opacity = 0
    }
  })
  const mountTween = gsap.to(root.position, {
    y: 0,
    duration: MOUNT_FADE_DURATION,
    ease: MOUNT_FADE_EASE,
  })
  const opacityTween = gsap.to(
    root,
    {
      // tween each mesh's material opacity
      onUpdate: () => {
        root.traverse((obj) => {
          if (obj.isMesh && obj.material && obj.material.opacity !== undefined) {
            obj.material.opacity = mountTween.progress()
          }
        })
      },
      duration: MOUNT_FADE_DURATION,
      ease: MOUNT_FADE_EASE,
    }
  )

  // -------------------------------------------------------------------------
  // Cleanup
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // stop GSAP timelines
    ghostTween.kill()
    pressTimeline.kill()
    mountTween.kill()
    opacityTween.kill()

    // dispose geometries / materials / textures
    panelGeometry.dispose()
    panelMaterial.dispose()

    ghostGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose()
        obj.material?.dispose()
      }
    })

    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose()
        obj.material?.dispose()
      }
    })

    buttonGeom.dispose()
    buttonMat.dispose()
    btnTexture.dispose()

    buttonGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose()
        obj.material?.dispose()
      }
    })

    // remove references
    root.clear()
  }

  return root
}
